<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Verifikasi Kepala Laboratorium</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.7/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#edf4f3}.card{max-width:760px;margin:7vh auto;border:0;border-radius:18px;box-shadow:0 12px 40px #1233}.seal{width:76px;height:76px;border-radius:50%;background:#087c70;color:#fff;display:grid;place-items:center;font-size:38px}</style></head><body><main class="container"><div class="card p-4 p-md-5"><div class="d-flex gap-4 align-items-center mb-4"><div class="seal">✓</div><div><span class="badge text-bg-success">TANDA TANGAN ELEKTRONIK VALID</span><h2 class="fw-bold mt-2 mb-0">Kepala Laboratorium</h2></div></div><table class="table"><tr><th>Nama</th><td><b>{{$setting->signer_name}}</b></td></tr><tr><th>Jabatan</th><td>{{$setting->signer_position}}</td></tr><tr><th>Nomor laporan</th><td>{{$project->number}}</td></tr><tr><th>Proyek</th><td>{{$project->name}}</td></tr><tr><th>Tanggal legalisasi</th><td>{{$project->legalized_at?->format('d/m/Y H:i')}} WITA</td></tr><tr><th>Kode tanda tangan</th><td><code>{{$expected}}</code></td></tr></table><a class="btn btn-success" href="{{route('public.verify',$project->verification_code)}}">Lihat legalisasi laporan</a></div></main></body></html>
